import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = total * ((line.discountPercent ?? 0) / 100);
  const amountAfterDiscount = total - discount;
  const vat = amountAfterDiscount * (line.vatRate / 100);
  return roundCents(vat);
}

export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discountTotal = 0;
  let vatTotal = 0;

  for (const line of invoice.lines) {
    const itemTotal = lineTotal(line);
    const itemDiscount = itemTotal * ((line.discountPercent ?? 0) / 100);
    const itemVAT = lineVAT(line);
    subtotal += itemTotal;
    discountTotal += itemDiscount;
    vatTotal += itemVAT;
  }

  const voucherAmount = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discountTotal + vatTotal - voucherAmount);
  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discountTotal),
    vat: Math.max(0, vatTotal),
    voucher: Math.max(0, voucherAmount),
    total,
  };
}

function calculateDueDate(issueDate, terms) {
  // Calculate due date based on payment terms
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Last day of month: move to 1st of next month, then subtract 1 day
    const [year, month] = issueDate.split('-').map(Number);
    const nextMonth = month === 12 ? 1 : month + 1;
    const nextYear = month === 12 ? year + 1 : year;
    const firstOfNextMonth = `${nextYear}-${String(nextMonth).padStart(2, '0')}-01`;
    return addDays(firstOfNextMonth, -1);
  }
  return null; // invalid terms
}

export function createInvoice({ customerId, issueDate, lines, terms }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate issueDate format and value
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and set payment terms (default to NET30)
  const finalTerms = terms ?? 'NET30';
  const dueDate = calculateDueDate(issueDate, finalTerms);
  if (!dueDate) return fail('TERMS_INVALID');

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate quantity is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discount percent
    let discountPercent;
    if (line.discountPercent !== undefined) {
      // Explicit discount provided (even if 0)
      if (typeof line.discountPercent !== 'number' || Number.isNaN(line.discountPercent) || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
      discountPercent = line.discountPercent;
    } else {
      // Use tier discount
      discountPercent = TIER_DISCOUNTS[customer.tier];
    }

    // Get product from catalogue
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    dueDate,
    terms: finalTerms,
    status: 'draft',
    lines: enrichedLines,
  };

  return ok(invoice);
}

export function addLine(invoice, { sku, qty, discountPercent }) {
  // Validate invoice is in draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate quantity is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get customer to determine tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Determine discount percent
  let discount;
  if (discountPercent !== undefined) {
    // Explicit discount provided (even if 0)
    if (typeof discountPercent !== 'number' || Number.isNaN(discountPercent) || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
    discount = discountPercent;
  } else {
    // Use tier discount
    discount = TIER_DISCOUNTS[customer.tier];
  }

  // Get product from catalogue
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array with shallow copies
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    // Update existing line with new quantity
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

export function removeLine(invoice, sku) {
  // Validate invoice is in draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line with this SKU
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if it would remove the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without this SKU
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

export function issueInvoice(invoice, existingNumbers) {
  // Validate invoice is in draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get the next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

export function applyVoucher(invoice, { code, amount }) {
  // Validate invoice is in draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  // Validate no voucher already applied
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

